@extends('layouts.app') @section('title','Your bag — LuxSkin') @section('content')<section class="section narrow"><span class="eyebrow">YOUR LITTLE TREASURES</span><h1>Your bag <em>({{ $items->sum('jumlah') }})</em></h1>@forelse($items as $item)<div class="cart-row"><img src="{{ $item->path_gambar ?: 'https://images.unsplash.com/photo-1601049541289-9b1b7bbbfe19?w=300' }}"><div class="cart-desc"><a href="{{ route('product',$item->slug) }}"><b>{{ $item->nama_produk }}</b></a><span>Rp{{ number_format($item->harga,0,',','.') }}</span><form method="POST" action="{{ route('cart.update',$item->id_detail_keranjang) }}">@csrf @method('PATCH')<input type="number" name="jumlah" min="1" max="20" value="{{ $item->jumlah }}"><button class="text-link">Update</button></form></div><b>Rp{{ number_format($item->harga*$item->jumlah,0,',','.') }}</b><form method="POST" action="{{ route('cart.remove',$item->id_detail_keranjang) }}">@csrf @method('DELETE')<button class="remove">×</button></form></div>@empty<div class="empty"><h2>Your bag is waiting.</h2><p>Belum ada produk di keranjangmu.</p><a class="btn dark" href="{{ route('catalog') }}">Start shopping ↗</a></div>@endforelse @if($items->isNotEmpty())<div class="cart-total"><span>Subtotal</span><b>Rp{{ number_format($items->sum(fn($i)=>$i->harga*$i->jumlah),0,',','.') }}</b></div><a class="btn dark checkout-btn" href="{{ route('checkout') }}">Continue to checkout ↗</a>@endif</section>@endsection